package wgmodern;
import net.minecraft.gametest.framework.*;import net.minecraft.core.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.item.*;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.phys.AABB;import net.minecraftforge.gametest.*;import net.minecraftforge.common.capabilities.ForgeCapabilities;
@GameTestHolder("witchinggadgets") @PrefixGameTestTemplate(false)
public class CreativeDeviceServerTests {
 @GameTest(template="empty",timeoutTicks=120) public static void lockOnlyAcceptsLegalMovesAndRemovesItsOwnFrame(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(3,3,3));for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)l.setBlockAndUpdate(p.offset(x,y,z),Content.OBSIDIAN_PLATE.get().defaultBlockState());l.setBlockAndUpdate(p,Content.LOCK.get().defaultBlockState());var unrelated=p.offset(1,1,1);l.setBlockAndUpdate(unrelated,Blocks.DIAMOND_BLOCK.defaultBlockState());var t=(TileLock.Tile)l.getBlockEntity(p);t.board=new int[]{0,1,2,3,4,5,6,8,7};h.assertTrue(!t.move(0)&&!t.unlocked,"Nonadjacent click cannot unlock");h.assertTrue(t.move(8)&&t.unlocked,"Solving final move starts removal");var tag=t.saveWithoutMetadata();var copy=new TileLock.Tile(p,t.getBlockState());copy.load(tag);h.assertTrue(copy.unlocked&&copy.ticks==0,"Unlocked timer persists");h.runAfterDelay(85,()->{h.assertTrue(l.getBlockState(p).isAir(),"Lock removes itself at 80 ticks");h.assertTrue(l.getBlockState(unrelated).is(Blocks.DIAMOND_BLOCK),"Only lock and obsidian-plate frame blocks are removed");h.assertTrue(l.getBlockState(p.below()).isAir(),"Bottom final pair removed");pass(h);});}
 @GameTest(template="empty") public static void sarcophagusDropsInventoryOnceAndBreakDoesNotDeleteNeighbours(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(4,2,4));var s=Content.SARCOPHAGUS.get().defaultBlockState();for(int i=-1;i<=1;i++)l.setBlockAndUpdate(p.east(i),s.setValue(Sarcophagus.PART,i+1));var t=(Sarcophagus.Tile)l.getBlockEntity(p);var diamonds=new ItemStack(Items.DIAMOND,17);diamonds.getOrCreateTag().putString("Owner","test");t.items.setStackInSlot(0,diamonds);var right=(Sarcophagus.Tile)l.getBlockEntity(p.east());h.assertTrue(right.getCapability(ForgeCapabilities.ITEM_HANDLER,Direction.UP).orElseThrow(IllegalStateException::new).getStackInSlot(0).getCount()==17,"All sides access the same six-slot tomb");var snapshot=t.saveWithoutMetadata();var loaded=new Sarcophagus.Tile(p,s);loaded.load(snapshot);h.assertTrue(ItemStack.matches(loaded.items.getStackInSlot(0),diamonds),"NBT inventory survives save");l.setBlockAndUpdate(p.north(),Blocks.EMERALD_BLOCK.defaultBlockState());l.removeBlock(p.east(),false);h.assertTrue(l.getBlockState(p).isAir()&&l.getBlockState(p.west()).isAir(),"Breaking a dummy removes all three parts");h.assertTrue(l.getBlockState(p.north()).is(Blocks.EMERALD_BLOCK),"Unrelated perpendicular block is retained");int total=l.getEntitiesOfClass(ItemEntity.class,new AABB(p).inflate(3)).stream().filter(e->e.getItem().is(Items.DIAMOND)&&e.getItem().getTag()!=null&&e.getItem().getTag().getString("Owner").equals("test")).mapToInt(e->e.getItem().getCount()).sum();h.assertTrue(total==17,"All tagged loot drops exactly once");pass(h);}
 private static void pass(GameTestHelper h){com.mojang.logging.LogUtils.getLogger().info("WITCHINGGADGETS_TEST_PASS {}",Thread.currentThread().getStackTrace()[2].getMethodName());h.succeed();}
}
